using System;using System.Data;using System.Text;using System.Web.Services;namespace WebPortal.Helpdesk{public partial class TicketReport:HelpdeskPage{protected void Page_Load(object sender,EventArgs e){if(Request.QueryString["export"]=="1")Export();}private static DateTime? Date(string value){DateTime d;return DateTime.TryParse(value,out d)?d:(DateTime?)null;}private void Export(){var t=SearchTable(Request.QueryString["ticketNo"],Date(Request.QueryString["from"]),Date(Request.QueryString["to"]),Int(Request.QueryString["requestTypeId"]),Request.QueryString["status"],Request.QueryString["priority"],Int(Request.QueryString["assignedTo"]),Request.QueryString["source"],Request.QueryString["approval"]);Response.Clear();Response.ContentType="application/vnd.ms-excel";Response.AddHeader("Content-Disposition","attachment; filename=IHMS_TicketReport_"+DateTime.Now.ToString("yyyyMMdd")+".xls");var b=new StringBuilder("<table><tr>");foreach(DataColumn c in t.Columns)b.Append("<th>").Append(Server.HtmlEncode(c.ColumnName)).Append("</th>");b.Append("</tr>");foreach(DataRow r in t.Rows){b.Append("<tr>");foreach(object v in r.ItemArray)b.Append("<td>").Append(Server.HtmlEncode(Convert.ToString(v))).Append("</td>");b.Append("</tr>");}b.Append("</table>");Response.Write(b.ToString());Context.ApplicationInstance.CompleteRequest();}private static int? Int(string value){int i;return Int32.TryParse(value,out i)?i:(int?)null;}private static DataTable SearchTable(string ticketNo,DateTime? from,DateTime? to,int? requestTypeId,string status,string priority,int? assignedTo,string source,string approval){return new HelpdeskRepository().Tickets(UserId,"All",status,ticketNo,from,to,requestTypeId,priority,assignedTo,source,approval);}[WebMethod]public static string Masters(){return Json(new HelpdeskRepository().Masters(UserId));}[WebMethod]public static string Search(string ticketNo,DateTime? from,DateTime? to,int? requestTypeId,string status,string priority,int? assignedTo,string source,string approval){return Json(SearchTable(ticketNo,from,to,requestTypeId,status,priority,assignedTo,source,approval));}}}
